const messages = Array.from({ length: 40 }, (_, index) => ({
  id: 'memory-message-' + index,
  role: index % 2 === 0 ? 'user' : 'assistant',
  content: index === 0
    ? 'Correction: project identifier is PRJ-991 and this exact value must remain available.'
    : index === 1
      ? 'Pending: confirm the production deployment window before taking any external action.'
      : 'Historical message ' + index + ': detailed operational discussion already completed and not needed verbatim in every future model request. Reference batch BATCH-' + String(index).padStart(3, '0') + '.',
  ...(index === 0 ? { kind: 'correction' } : {}),
  ...(index === 1 ? { kind: 'pending' } : {})
}));
const originalText = JSON.stringify(messages);
return [{ json: { messages, originalEstimatedTokens: Math.ceil(originalText.length / 4) } }];

const source = $('Gerar histórico crescente').first().json;
const memory = $('Montar contexto compacto').first().json;
const original = Number(source.originalEstimatedTokens || 0);
const optimized = Number(memory.estimatedTokens || 0);
const percent = original > 0 ? Number((((original - optimized) / original) * 100).toFixed(2)) : 0;
const context = String(memory.context || '');
const checks = {
  reductionAtLeast70Percent: percent >= 70,
  currentFactOnlyOnce: (context.match(/\"priority\":\"critical\"/g) || []).length === 1,
  supersededFactOmitted: !context.includes('\"priority\":\"low\"'),
  correctionProtected: context.includes('PRJ-991'),
  pendingProtected: context.includes('production deployment window'),
  oldMessagesArchived: Number(memory.archivedEventCount || 0) === 37
};
if (Object.values(checks).some((value) => !value)) throw new Error('Context Saver Memory runtime smoke failed: ' + JSON.stringify({ checks, original, optimized, percent, context }));
return [{ json: { passed: true, checks, tokens: { originalHistory: original, compactMemory: optimized, saved: original - optimized, percent }, included: memory.included, archivedEventCount: memory.archivedEventCount } }];
